<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { agregarInteraccion,cerrarTicket,crearTareaTicket,crearTicket,detalleTicket,eliminarTicket,liberarTicket,listarTickets,recibirTicket,type Options,type Ticket } from '../services/callCenter'
const emptyOptions:Options={tipos_atencion:[],medios:[],distritos:[],secciones:[],tipos_interaccion:[]}
const rows=ref<Ticket[]>([]),options=ref<Options>(emptyOptions),detail=ref<Ticket|null>(null),modal=ref<'nuevo'|'interaccion'|'tarea'|'cerrar'|null>(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),total=ref(0),lastPage=ref(1),file=ref<File|null>(null)
const filters=reactive({bandeja:'todos',criterio:'',tipo_atencion_id:'',desde:'',hasta:'',page:1})
const ticket=reactive({dni:'',apellido_paterno:'',apellido_materno:'',nombre:'',celular:'',email:'',telefono_fijo:'',tipo_atencion_id:'',medio_recepcion:'',detalle:'',suministro_id:'',distrito_id:'',referencia:'',latitud:'',longitud:''})
const interaction=reactive({tipo_interaccion:'',descripcion:''}),task=reactive({seccion_id:'',descripcion:''}),close=reactive({descripcion:'',tipo_interaccion:''})
const msg=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarTickets(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options||emptyOptions}catch(e){error.value=msg(e)}finally{loading.value=false}}
async function show(x:Ticket){try{detail.value=await detalleTicket(x.id)}catch(e){error.value=msg(e)}}
function open(type:typeof modal.value,x?:Ticket){if(x)detail.value=x;modal.value=type;file.value=null;Object.assign(interaction,{tipo_interaccion:'',descripcion:''});Object.assign(task,{seccion_id:'',descripcion:''});Object.assign(close,{descripcion:'',tipo_interaccion:''})}
async function state(x:Ticket,type:'recibir'|'liberar'|'eliminar'){if(!confirm(`¿Confirmar ${type} el ticket #${x.id}?`))return;try{if(type==='recibir')await recibirTicket(x.id);else if(type==='liberar')await liberarTicket(x.id);else await eliminarTicket(x.id);success.value='Ticket actualizado correctamente.';detail.value=null;await load()}catch(e){error.value=msg(e)}}
async function submit(){saving.value=true;error.value='';try{if(modal.value==='nuevo'){if(!/^\d{8}$/.test(ticket.dni)||!/^\d{9}$/.test(ticket.celular)||ticket.detalle.trim().length<20)throw new Error('Ingrese DNI, celular y un detalle de al menos 20 caracteres.');await crearTicket({...ticket})}else if(detail.value&&modal.value==='interaccion'){if(interaction.descripcion.trim().length<5)throw new Error('La descripción debe tener al menos 5 caracteres.');const data=new FormData();data.append('tipo_interaccion',interaction.tipo_interaccion);data.append('descripcion',interaction.descripcion);if(file.value)data.append('archivo',file.value);await agregarInteraccion(detail.value.id,data)}else if(detail.value&&modal.value==='tarea'){await crearTareaTicket(detail.value.id,{...task})}else if(detail.value&&modal.value==='cerrar'){await cerrarTicket(detail.value.id,{...close})}success.value='Operación registrada correctamente.';modal.value=null;detail.value=null;await load(1)}catch(e){error.value=msg(e)}finally{saving.value=false}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Call Center</nav><header class="hero"><div class="mark">CC</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Call Center</h1><p>Registro, asignación y seguimiento de atenciones ciudadanas.</p></div><strong>{{total}} tickets</strong><button @click="open('nuevo')">+ Nuevo ticket</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><div class="tabs"><button v-for="x in [{id:'todos',n:'Todos'},{id:'pendientes',n:'Pendientes'},{id:'mis-tickets',n:'Mis tickets'},{id:'finalizados',n:'Finalizados'}]" :key="x.id" :class="{active:filters.bandeja===x.id}" @click="filters.bandeja=x.id;load(1)">{{x.n}}</button></div><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Ticket, DNI o suministro" @keyup.enter="load(1)"></label><label>Tipo de atención<select v-model="filters.tipo_atencion_id"><option value="">Todos</option><option v-for="x in options.tipos_atencion" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando tickets…</div><div v-else-if="!rows.length" class="empty">No existen tickets en esta bandeja.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><div><small>{{x.tipo_atencion}}</small><b>Ticket #{{x.id}}</b></div><em>{{x.estado}}</em></header><h2>{{x.cliente}}</h2><p>{{x.detalle}}</p><dl><div><dt>DNI</dt><dd>{{x.dni}}</dd></div><div><dt>Suministro</dt><dd>{{x.suministro||'—'}}</dd></div><div><dt>Responsable</dt><dd>{{x.responsable||'Sin asignar'}}</dd></div><div><dt>Recepción</dt><dd>{{x.fecha_recepcion}}</dd></div></dl><footer><button @click="show(x)">Ver detalle</button><button v-if="x.puede_recibir" class="good" @click="state(x,'recibir')">Recibir</button><button v-if="x.puede_liberar" @click="state(x,'liberar')">Liberar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="detail&&!modal" class="backdrop" @mousedown.self="detail=null"><section class="modal wide"><header><div><small>TICKET #{{detail.id}}</small><h2>{{detail.cliente}}</h2><p>{{detail.tipo_atencion}} · {{detail.estado}}</p></div><button @click="detail=null">×</button></header><p class="description">{{detail.detalle}}</p><div class="summary"><div><b>{{detail.dni}}</b><span>DNI</span></div><div><b>{{detail.suministro||'—'}}</b><span>Suministro</span></div><div><b>{{detail.responsable||'Sin asignar'}}</b><span>Responsable</span></div></div><h3>Interacciones</h3><div class="list"><div v-for="x in detail.interacciones" :key="x.id"><span><b>{{x.tipo}}</b><br>{{x.descripcion}}</span><small>{{x.usuario}} · {{x.fecha}}</small></div><p v-if="!detail.interacciones?.length">Sin interacciones registradas.</p></div><h3>Tareas vinculadas</h3><div class="list"><div v-for="x in detail.tareas" :key="x.id"><span><b>#{{x.id}} · {{x.seccion}}</b><br>{{x.descripcion}}</span><small>{{x.estado}} · {{x.fecha}}</small></div></div><footer><button class="clear" @click="detail=null">Cerrar</button><button @click="open('interaccion')">Registrar interacción</button><button @click="open('tarea')">Crear tarea</button><button v-if="detail.puede_cerrar" class="good" @click="open('cerrar')">Finalizar ticket</button><button v-if="detail.puede_eliminar" class="danger" @click="state(detail,'eliminar')">Eliminar</button></footer></section></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=null"><form class="modal" @submit.prevent="submit"><header><div><small>CALL CENTER</small><h2>{{modal==='nuevo'?'Registrar ticket':modal==='interaccion'?'Nueva interacción':modal==='tarea'?'Asignar tarea':'Finalizar ticket'}}</h2></div><button type="button" @click="modal=null">×</button></header><template v-if="modal==='nuevo'"><div class="grid"><label>DNI *<input v-model="ticket.dni" maxlength="8"></label><label>Celular *<input v-model="ticket.celular" maxlength="9"></label><label>Nombre *<input v-model="ticket.nombre"></label><label>Apellido paterno<input v-model="ticket.apellido_paterno"></label><label>Apellido materno<input v-model="ticket.apellido_materno"></label><label>Correo<input v-model="ticket.email" type="email"></label><label>Tipo de atención *<select v-model="ticket.tipo_atencion_id"><option value="">Seleccione</option><option v-for="x in options.tipos_atencion" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Medio de recepción<select v-model="ticket.medio_recepcion"><option value="">Seleccione</option><option v-for="x in options.medios" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Suministro<input v-model="ticket.suministro_id"></label><label>Distrito<select v-model="ticket.distrito_id"><option value="">Seleccione</option><option v-for="x in options.distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><label>Referencia<input v-model="ticket.referencia"></label><label>Detalle *<textarea v-model="ticket.detalle" minlength="20" rows="4"></textarea></label></template><template v-else-if="modal==='interaccion'"><label>Tipo de interacción *<select v-model="interaction.tipo_interaccion" required><option value="">Seleccione</option><option v-for="x in options.tipos_interaccion" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Descripción *<textarea v-model="interaction.descripcion" minlength="5" rows="5" required></textarea></label><label>Archivo<input type="file" @change="file=($event.target as HTMLInputElement).files?.[0]||null"><small>Máximo 20 MB.</small></label></template><template v-else-if="modal==='tarea'"><label>Sección responsable *<select v-model="task.seccion_id" required><option value="">Seleccione</option><option v-for="x in options.secciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Indicaciones *<textarea v-model="task.descripcion" rows="5" required></textarea></label></template><template v-else><label>Tipo de interacción<select v-model="close.tipo_interaccion"><option value="">Seleccione</option><option v-for="x in options.tipos_interaccion" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Resultado de la atención *<textarea v-model="close.descripcion" rows="5" required></textarea></label></template><footer><button type="button" class="clear" @click="modal=null">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#1689a5;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.56rem}.flash{padding:10px;background:#eaf8f8;font-size:.63rem}.error{color:#a13f43;background:#fff0f0}.tabs{margin-top:13px;display:flex;gap:4px}.tabs button{padding:10px 16px;border:0;border-radius:7px 7px 0 0;color:#718087;background:#e7ebed;font-size:.56rem}.tabs .active{color:#fff;background:var(--a)}.filters{padding:12px;display:flex;align-items:end;gap:7px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.59rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:14px;border-top:3px solid var(--a);border-radius:9px;background:#fff}.cards article>header{display:flex;justify-content:space-between}.cards header small,.cards header b{display:block}.cards header em{padding:4px 7px;border-radius:10px;background:#eaf8f8;font-size:.48rem;font-style:normal}.cards h2{font-size:.65rem}.cards article>p{min-height:38px;color:#69777d;font-size:.55rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.cards dt{color:#8a969c;font-size:.46rem}.cards dd{margin:2px 0;font-size:.51rem;font-weight:700}.cards footer{margin-top:auto;display:flex;justify-content:flex-end}.cards footer button{border:0;background:none;font-size:.49rem}.good{color:var(--a)!important}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,760px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.wide{width:min(100%,900px)}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.description{padding:11px;border-left:3px solid var(--a);background:#f6f8f9;font-size:.57rem}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.summary div{padding:10px;text-align:center;background:#eaf8f8}.summary b,.summary span{display:block;font-size:.53rem}.modal h3{font-size:.65rem}.list div{padding:8px;display:flex;justify-content:space-between;border-bottom:1px solid #edf0f2;font-size:.53rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.danger{background:#bd4b55!important}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.cards,.grid,.summary{grid-template-columns:1fr}.tabs{overflow:auto}}
</style>
